export const THIRD_PARTY_KIT_SCHEMA = 'gripforge.kit-module/1';
/** The exports of the calls contract a kit module must have (gripforge-kit-guest `export_kit!`). */
export const KIT_MODULE_EXPORTS = ['memory', 'gf_alloc', 'gf_on_bridge', 'gf_calls_init'] as const;
/** The kits that live in the core (`kithost.core`): they have no module of their own. */
export const KITS_IN_CORE: readonly string[] = ['game.engine'];

/** `kit.json`, written by the author of the kit. */
export interface ThirdPartyKitManifest {
  schema: string;
  id: string;
  version: string;
  description?: string;
  provides: string[];
  consumes: string[];
  services?: string[];
  requires?: string[];
  optional?: string[];
}

/** One declared third-party kit (`project.thirdPartyKits[]`). */
export interface ThirdPartyKitDecl {
  id: string;
  version: string;
  /** Where the module is: a path relative to the game file (`./kits/acme.streak.wasm`), or an `http(s)://` URL. */
  source: string;
  /** SHA-256 of the module, 64 hexadecimal digits: what is loaded must have it. */
  sha256: string;
  bytes: number;
  manifest: ThirdPartyKitManifest;
}

/** `lock.thirdParty[id]`: the version and the fingerprint the lock froze. */
export interface ThirdPartyKitLock { version: string; sha256: string; bytes: number }

/** The part of a game file this module reads and writes (a project bundle: `{ project, lock }`). */
export interface ThirdPartyGame {
  project: {
    installed?: Array<{ id: string; version: string; enabled?: boolean; config?: Record<string, unknown> } & Record<string, unknown>>;
    thirdPartyKits?: ThirdPartyKitDecl[];
    logic?: unknown;
  } & Record<string, unknown>;
  lock: {
    order?: string[];
    kits?: Record<string, ({ version: string; enabled?: boolean } & Record<string, unknown>) | undefined>;
    thirdParty?: Record<string, ThirdPartyKitLock | undefined>;
  } & Record<string, unknown>;
}

/** `kit-modules.json` of a folder of kit modules, as far as this module reads it. */
export interface KitModulesIndex {
  schema?: string;
  contract?: string;
  core?: { name?: string; version?: string; wasm?: string; provides?: string[] } | null;
  kits?: Record<string, { version?: string; wasm?: string; bytes?: number; hash?: string; sha256?: string; thirdParty?: boolean } | undefined>;
  merged?: { wasm?: string; kits?: string[] } | null;
}

const list = (v: unknown): string[] => (Array.isArray(v) ? v.map(String) : []);
const KIT_ID = /^[a-z][a-z0-9_]*(\.[a-z][a-z0-9_]*)+$/;
const SHA256 = /^[a-f0-9]{64}$/;

// ─── versions (the rules of native/gripforge-runtime/web/module-calls.mjs) ───

export function parseKitVersion(s: unknown): [number, number, number] | null {
  const core = String(s ?? '').split(/[-+]/)[0]!.split('.');
  if (core.length < 1 || core.length > 3 || core.some((x) => !/^\d+$/.test(x))) return null;
  return [Number(core[0] ?? 0), Number(core[1] ?? 0), Number(core[2] ?? 0)];
}
const cmp = (a: number[], b: number[]) => a[0]! - b[0]! || a[1]! - b[1]! || a[2]! - b[2]!;

/** `*`, `=x`, `~x`, `^x` or bare `x` (a caret), `>=x`. */
export function kitVersionMatches(req: unknown, version: unknown): boolean {
  const v = parseKitVersion(version);
  if (!v) return false;
  const text = String(req ?? '').trim();
  if (text === '' || text === '*') return true;
  const m = /^(>=|=|~|\^)?(.*)$/.exec(text)!;
  const op = m[1] ?? '^', want = parseKitVersion(m[2]!.trim());
  if (!want) return false;
  if (op === '>=') return cmp(v, want) >= 0;
  if (op === '=') return cmp(v, want) === 0;
  if (op === '~') return v[0] === want[0] && v[1] === want[1] && cmp(v, want) >= 0;
  return want[0] > 0 ? v[0] === want[0] && cmp(v, want) >= 0 : v[0] === 0 && v[1] === want[1] && cmp(v, want) >= 0;
}

/** `name@requirement` → [name, requirement] (no `@`: any version). */
export const splitKitTarget = (t: string): [string, string] => { const i = t.indexOf('@'); return i < 0 ? [t, '*'] : [t.slice(0, i), t.slice(i + 1)]; };

// ─── the manifest ────────────────────────────────────────────────────────────

/** The problems of a kit manifest alone (no binary): empty when it is well formed. */
export function kitManifestIssues(kit: unknown): string[] {
  if (!kit || typeof kit !== 'object' || Array.isArray(kit)) return ['kit.json: not an object'];
  const k = kit as Record<string, unknown>, issues: string[] = [];
  if (k.schema !== THIRD_PARTY_KIT_SCHEMA) issues.push(`kit.json: "schema" must be "${THIRD_PARTY_KIT_SCHEMA}" (got ${JSON.stringify(k.schema)})`);
  if (typeof k.id !== 'string' || !KIT_ID.test(k.id)) issues.push(`kit.json: "id" must be a dotted lowercase id of your own, like "acme.streak" (got ${JSON.stringify(k.id)})`);
  if (!parseKitVersion(k.version) || String(k.version).split('.').length !== 3) issues.push(`kit.json: "version" must be major.minor.patch (got ${JSON.stringify(k.version)})`);
  for (const key of ['provides', 'services']) for (const p of list(k[key])) {
    const [name, v] = splitKitTarget(p);
    if (!name || !parseKitVersion(v) || /^[\^~=>*]/.test(v)) issues.push(`kit.json: ${key} "${p}" must be name@major.minor.patch (an exact version: it is what the kit gives)`);
  }
  for (const key of ['consumes', 'requires', 'optional']) for (const p of list(k[key])) {
    const [name, req] = splitKitTarget(p);
    if (!name || !p.includes('@') || (req !== '*' && !parseKitVersion(req.replace(/^(>=|=|~|\^)/, '')))) issues.push(`kit.json: ${key} "${p}" must be name@requirement (like "kithost.world@^1.0")`);
  }
  if (!list(k.provides).some((p) => splitKitTarget(p)[0] === 'kithost.kit')) issues.push('kit.json: "provides" must hold "kithost.kit@1.0.0" (the hooks the core calls)');
  return issues;
}

// ─── the binary ──────────────────────────────────────────────────────────────

/** What a kit module says of itself: its exports and the lines of its custom section `gripforge.calls`. */
export interface KitWasmInfo { exports: string[]; contracts: string[] }

/** Reads the export names and the `gripforge.calls` section of a WebAssembly module. Throws when it is not one. */
export function inspectKitWasm(bytes: Uint8Array): KitWasmInfo {
  if (bytes.length < 8 || bytes[0] !== 0x00 || bytes[1] !== 0x61 || bytes[2] !== 0x73 || bytes[3] !== 0x6d) throw new Error('not a WebAssembly module (no \\0asm header)');
  let at = 8;
  const leb = (): number => { let result = 0, shift = 0; for (;;) { if (at >= bytes.length) throw new Error('truncated WebAssembly module'); const b = bytes[at++]!; result += (b & 0x7f) * 2 ** shift; shift += 7; if (!(b & 0x80)) return result; } };
  const text = (from: number, to: number): string => { let s = ''; for (let i = from; i < to; i++) s += String.fromCharCode(bytes[i]!); try { return decodeURIComponent(escape(s)); } catch { return s; } };
  const name = (): string => { const n = leb(), from = at; at += n; if (at > bytes.length) throw new Error('truncated WebAssembly module'); return text(from, at); };
  const info: KitWasmInfo = { exports: [], contracts: [] };
  while (at < bytes.length) {
    const id = bytes[at++]!, size = leb(), end = at + size;
    if (end > bytes.length) throw new Error('truncated WebAssembly module');
    if (id === 7) { for (let n = leb(); n > 0; n--) { info.exports.push(name()); at++; leb(); } }
    else if (id === 0 && name() === 'gripforge.calls') info.contracts.push(...text(at, end).split('\n').map((l) => l.trim()).filter(Boolean));
    at = end;
  }
  return info;
}

/** What `checkThirdPartyKit` found: `issues` refuse the kit, `warnings` do not. */
export interface ThirdPartyCheck { issues: string[]; warnings: string[] }

/**
 * A kit module against its manifest and, when given, the folder of kit modules it will be played with
 * (`kit-modules.json`): each message says what to change.
 * - the binary exports the calls contract and has the `gripforge.calls` section;
 * - `provides` / `consumes` of the manifest are the lines of that section;
 * - every `consumes` is met by what the core provides (same major, core not older);
 * - every `requires` is a kit of the folder at a matching version (`optional`: a warning);
 * - the id is not the id of a GripForge kit.
 */
export function checkThirdPartyKit(input: { manifest: unknown; wasm: Uint8Array; modules?: KitModulesIndex | null; reserved?: (id: string) => boolean }): ThirdPartyCheck {
  const issues = kitManifestIssues(input.manifest), warnings: string[] = [];
  if (issues.length) return { issues, warnings };
  const kit = input.manifest as ThirdPartyKitManifest;
  let info: KitWasmInfo;
  try { info = inspectKitWasm(input.wasm); } catch (error) { return { issues: [`the kit binary: ${(error as Error).message} — build the kit with "cargo build --release --target wasm32-unknown-unknown"`], warnings }; }
  const missing = KIT_MODULE_EXPORTS.filter((e) => !info.exports.includes(e));
  if (missing.length) issues.push(`the binary does not export ${missing.join(', ')}: the crate must be a cdylib ([lib] crate-type = ["cdylib"]) that calls gripforge_kit_guest::export_kit!(…)`);
  const lines = (kind: string) => info.contracts.filter((l) => l.startsWith(`${kind} `)).map((l) => l.slice(kind.length + 1).trim());
  if (!info.contracts.length) issues.push('the binary has no "gripforge.calls" section: it was not built with export_kit! (or was built for another target than wasm32-unknown-unknown)');
  else for (const key of ['provides', 'consumes'] as const) {
    const inBinary = [...lines(key)].sort(), inManifest = [...list(kit[key])].sort();
    if (JSON.stringify(inBinary) !== JSON.stringify(inManifest)) {
      const extra = inManifest.filter((x) => !inBinary.includes(x)), absent = inBinary.filter((x) => !inManifest.includes(x));
      issues.push(`kit.json "${key}" is not what the binary declares:${absent.length ? ` add ${absent.map((x) => `"${x}"`).join(', ')};` : ''}${extra.length ? ` remove ${extra.map((x) => `"${x}"`).join(', ')};` : ''} the binary says [${inBinary.join(', ')}]`);
    }
  }
  if (input.reserved?.(kit.id)) issues.push(`"${kit.id}" is the id of a GripForge kit: choose an id under a prefix of your own`);
  const modules = input.modules;
  if (modules) {
    const core = modules.core;
    if (!core) issues.push('kit-modules.json: no core');
    else {
      const provided = new Map(list(core.provides).map((p) => splitKitTarget(p)));
      for (const c of lines('consumes').length ? lines('consumes') : list(kit.consumes)) {
        const [name, req] = splitKitTarget(c), have = provided.get(name);
        if (!have) issues.push(`the kit consumes ${c}, which the core ${core.name}@${core.version} does not provide (it provides ${[...provided.keys()].join(', ')})`);
        else if (!kitVersionMatches(req, have)) issues.push(`the kit consumes ${c}, the core provides ${name}@${have}: ${parseKitVersion(req.replace(/^\D+/, ''))?.[0] !== parseKitVersion(have)?.[0] ? 'another major version — rebuild the kit against the gripforge-kit-guest of this core' : 'the core is older than the interface the kit was built against — update the core, or build the kit against the older gripforge-kit-guest'}`);
      }
    }
    const need = (spec: string, optional: boolean) => {
      const [name, req] = splitKitTarget(spec), have = modules.kits?.[name];
      const say = (m: string) => (optional ? warnings : issues).push(m);
      if (KITS_IN_CORE.includes(name)) return;
      if (!have) say(`${optional ? 'optional kit' : 'required kit'} ${spec} has no kit module here (${optional ? 'the kit runs without it' : 'the game must install it'})`);
      else if (!kitVersionMatches(req, have.version)) say(`${optional ? 'optional kit' : 'required kit'} ${spec}: the kit modules have ${name}@${have.version}`);
    };
    for (const r of list(kit.requires)) need(r, false);
    for (const r of list(kit.optional)) need(r, true);
    const previous = modules.kits?.[kit.id];
    if (previous && !previous.thirdParty && !input.reserved?.(kit.id)) issues.push(`"${kit.id}" is already a kit of these kit modules (a GripForge kit): choose an id under a prefix of your own`);
  }
  return { issues, warnings };
}

// ─── the declaration in a game ───────────────────────────────────────────────

/** The declared third-party kits of a project (an empty list when it has none). */
export function thirdPartyKits(project: { thirdPartyKits?: unknown } | null | undefined): ThirdPartyKitDecl[] {
  const all = project?.thirdPartyKits;
  return Array.isArray(all) ? all.filter((k): k is ThirdPartyKitDecl => !!k && typeof k === 'object' && typeof (k as ThirdPartyKitDecl).id === 'string') : [];
}

/** The ids of the declared third-party kits that are installed and enabled: the ones a page has to load. */
export function thirdPartyKitIds(project: { thirdPartyKits?: unknown; installed?: Array<{ id: string; enabled?: boolean }> } | null | undefined): string[] {
  const installed = project?.installed ?? [];
  return thirdPartyKits(project).map((k) => k.id).filter((id) => installed.some((k) => k.id === id && k.enabled !== false));
}

/** The file name of a kit module in a folder of kit modules: its id and the first 16 digits of its SHA-256. */
export const thirdPartyModuleFile = (id: string, sha256: string): string => `kit.${id}.${sha256.slice(0, 16)}.wasm`;

/** The line of a third-party kit in `kit-modules.json`. */
export function thirdPartyModuleEntry(decl: ThirdPartyKitDecl) {
  return { version: decl.version, wasm: thirdPartyModuleFile(decl.id, decl.sha256), bytes: decl.bytes, hash: decl.sha256.slice(0, 16), sha256: decl.sha256, thirdParty: true,
    provides: list(decl.manifest.provides), consumes: list(decl.manifest.consumes), services: list(decl.manifest.services) };
}

/**
 * The game with the kit declared (added, or replaced when its id is already declared): the declaration, its entry
 * in `installed` (the config is kept when the kit is replaced, unless `config` is given), its place in `lock.order`
 * (kept; a new kit goes at the end, after the kits it requires) and the lock lines. Nothing is mutated.
 */
export function declareThirdPartyKit<G extends ThirdPartyGame>(game: G, decl: ThirdPartyKitDecl, options: { config?: Record<string, unknown>; now?: string } = {}): G {
  const issues = declarationIssues(decl);
  if (issues.length) throw new Error(issues.join('\n'));
  const installed = [...(game.project.installed ?? [])], at = installed.findIndex((k) => k.id === decl.id);
  const previous = at >= 0 ? installed[at]! : null;
  // An entry written by hand before the declaration existed is adopted (its config and its place are kept); that the
  // id is not a GripForge kit is checked by the callers, which know the registry or the kit modules (`reserved`, `known`).
  const entry = { ...(previous ?? { source: 'user', installedAt: options.now ?? new Date().toISOString() }), id: decl.id, version: decl.version, enabled: previous?.enabled ?? true, config: options.config ?? previous?.config ?? {} };
  if (at >= 0) installed[at] = entry; else installed.push(entry);
  const order = [...(game.lock.order ?? [])];
  if (!order.includes(decl.id)) order.push(decl.id);
  return {
    ...game,
    project: { ...game.project, installed, thirdPartyKits: [...thirdPartyKits(game.project).filter((k) => k.id !== decl.id), decl] },
    lock: { ...game.lock, order,
      kits: { ...(game.lock.kits ?? {}), [decl.id]: { ...(game.lock.kits?.[decl.id] ?? {}), version: decl.version, enabled: entry.enabled } },
      thirdParty: { ...(game.lock.thirdParty ?? {}), [decl.id]: { version: decl.version, sha256: decl.sha256, bytes: decl.bytes } } },
  };
}

/** The game without the kit: its declaration, its `installed` entry and its lock lines. Throws when it is not a declared third-party kit. */
export function removeThirdPartyKit<G extends ThirdPartyGame>(game: G, id: string): G {
  if (!thirdPartyKits(game.project).some((k) => k.id === id)) throw new Error(`${id} is not a declared third-party kit of this game (declared: ${thirdPartyKits(game.project).map((k) => k.id).join(', ') || 'none'})`);
  const { [id]: _kit, ...kits } = game.lock.kits ?? {};
  const { [id]: _locked, ...thirdParty } = game.lock.thirdParty ?? {};
  const rest = thirdPartyKits(game.project).filter((k) => k.id !== id);
  const project = { ...game.project, installed: (game.project.installed ?? []).filter((k) => k.id !== id), thirdPartyKits: rest };
  if (!rest.length) delete (project as { thirdPartyKits?: unknown }).thirdPartyKits;
  const lock = { ...game.lock, order: (game.lock.order ?? []).filter((k) => k !== id), kits, thirdParty };
  if (!Object.keys(thirdParty).length) delete (lock as { thirdParty?: unknown }).thirdParty;
  return { ...game, project, lock };
}

/** The problems of one declaration alone. */
export function declarationIssues(decl: unknown): string[] {
  if (!decl || typeof decl !== 'object') return ['a third-party kit declaration must be an object { id, version, source, sha256, bytes, manifest }'];
  const d = decl as Partial<ThirdPartyKitDecl>, issues: string[] = [], who = typeof d.id === 'string' ? d.id : 'third-party kit';
  if (typeof d.id !== 'string' || !KIT_ID.test(d.id)) issues.push(`${who}: "id" must be a dotted lowercase id (got ${JSON.stringify(d.id)})`);
  if (!parseKitVersion(d.version) || String(d.version).split('.').length !== 3) issues.push(`${who}: "version" must be major.minor.patch (got ${JSON.stringify(d.version)})`);
  if (typeof d.source !== 'string' || !d.source) issues.push(`${who}: "source" must be a path relative to the game file or an http(s) URL`);
  else if (/^[a-z][a-z0-9+.-]*:/i.test(d.source) && !/^https?:\/\//i.test(d.source)) issues.push(`${who}: "source" ${d.source} — only a relative path or an http(s) URL`);
  if (typeof d.sha256 !== 'string' || !SHA256.test(d.sha256)) issues.push(`${who}: "sha256" must be the 64 hexadecimal digits of the module's SHA-256`);
  if (!Number.isSafeInteger(d.bytes) || (d.bytes ?? 0) <= 0) issues.push(`${who}: "bytes" must be the size of the module`);
  const m = kitManifestIssues(d.manifest);
  if (m.length) issues.push(...m.map((x) => `${who}: ${x}`));
  else {
    if (d.manifest!.id !== d.id) issues.push(`${who}: the manifest is the one of ${d.manifest!.id}`);
    if (d.manifest!.version !== d.version) issues.push(`${who}: declared at ${String(d.version)}, its manifest says ${d.manifest!.version}`);
  }
  return issues;
}

/**
 * Whether a game and its declared third-party kits agree — the declaration, `installed`, the lock, and (when given)
 * the kit modules the page will load. Each message names the kit and the two values that differ.
 * `known(id)`: whether an id is a GripForge kit (the registry); with it, an installed kit that is neither one nor
 * declared is reported — the rule: a third-party module is loaded only when the game declares it.
 */
export function thirdPartyIssues(game: ThirdPartyGame, options: { modules?: KitModulesIndex | null; known?: (id: string) => boolean } = {}): string[] {
  const issues: string[] = [], declared = thirdPartyKits(game.project), installed = game.project.installed ?? [], order = game.lock.order ?? [];
  const seen = new Set<string>();
  for (const decl of declared) {
    if (seen.has(decl.id)) { issues.push(`${decl.id}: declared twice in project.thirdPartyKits`); continue; }
    seen.add(decl.id);
    const own = declarationIssues(decl);
    issues.push(...own);
    if (own.length) continue;
    if (options.known?.(decl.id)) issues.push(`${decl.id}: this is the id of a GripForge kit — a third-party kit needs an id under a prefix of its own`);
    const entry = installed.find((k) => k.id === decl.id);
    if (!entry) issues.push(`${decl.id}: declared in project.thirdPartyKits but not in project.installed — it is not played (add its entry, or remove the declaration)`);
    else if (entry.version !== decl.version) issues.push(`${decl.id}: installed at ${entry.version}, declared at ${decl.version} — declare the kit again (gripforge kit add) so that the three agree`);
    if (entry && entry.enabled !== false && !order.includes(decl.id)) issues.push(`${decl.id}: not in lock.order — it is never mounted`);
    const locked = game.lock.thirdParty?.[decl.id];
    if (!locked) issues.push(`${decl.id}: the lock does not freeze it (no lock.thirdParty["${decl.id}"]) — declare it again with the CLI or the MCP tool`);
    else {
      if (locked.version !== decl.version) issues.push(`${decl.id}: the lock froze version ${locked.version}, the project declares ${decl.version} — declare the kit again (gripforge kit add) so that the three agree`);
      if (locked.sha256 !== decl.sha256) issues.push(`${decl.id}: the lock froze sha256 ${locked.sha256.slice(0, 16)}…, the project declares ${decl.sha256.slice(0, 16)}… — declare the kit again (gripforge kit add) so that the three agree`);
    }
    const lockedKit = game.lock.kits?.[decl.id];
    if (lockedKit && lockedKit.version !== decl.version) issues.push(`${decl.id}: lock.kits says ${lockedKit.version}, the project declares ${decl.version} — declare the kit again (gripforge kit add) so that the three agree`);
    const have = new Map<string, string>();
    for (const k of installed) if (k.enabled !== false) have.set(k.id, k.version);
    for (const spec of list(decl.manifest.requires)) {
      const [name, req] = splitKitTarget(spec), version = have.get(name);
      if (!version) issues.push(`${decl.id}: requires ${spec}, which the game does not install`);
      else if (!kitVersionMatches(req, version)) issues.push(`${decl.id}: requires ${spec}, the game installs ${name}@${version}`);
    }
    const module = options.modules?.kits?.[decl.id];
    if (options.modules && entry && entry.enabled !== false) {
      if (!module?.wasm) issues.push(`${decl.id}: no kit module in kit-modules.json — the page cannot load it`);
      else {
        if (module.version !== decl.version) issues.push(`${decl.id}: the kit module is version ${String(module.version)}, the game declares ${decl.version} — the kit modules hold another build of the kit (gripforge kit add puts the declared one there; or export again)`);
        const fingerprint = module.sha256 ?? module.hash;
        if (fingerprint && !decl.sha256.startsWith(fingerprint)) issues.push(`${decl.id}: the kit module has sha256 ${fingerprint.slice(0, 16)}…, the game declares ${decl.sha256.slice(0, 16)}… — not the binary that was declared`);
      }
    }
  }
  for (const id of Object.keys(game.lock.thirdParty ?? {})) if (!seen.has(id)) issues.push(`${id}: frozen in lock.thirdParty but not declared in project.thirdPartyKits`);
  if (options.known) for (const k of installed) if (!seen.has(k.id) && !options.known(k.id)) issues.push(`${k.id}: installed, but it is neither a GripForge kit nor a declared third-party kit — a third-party module is loaded only when the game declares it (gripforge kit add, or the MCP tool gripforge_third_party_kit_add)`);
  return issues;
}

/** One line per declared kit, for the CLI and the MCP. */
export function thirdPartySummary(game: ThirdPartyGame): Array<{ config: Record<string, unknown>; mounts: number; id: string; version: string; source: string; sha256: string; bytes: number; enabled: boolean; installed: boolean; locked: boolean; services: string[]; requires: string[]; optional: string[] }> {
  return thirdPartyKits(game.project).map((k) => {
    const entry = (game.project.installed ?? []).find((i) => i.id === k.id), locked = game.lock.thirdParty?.[k.id];
    return { config: entry?.config ?? {}, mounts: (game.lock.order ?? []).indexOf(k.id) + 1, id: k.id, version: k.version, source: k.source, sha256: k.sha256, bytes: k.bytes, enabled: !!entry && entry.enabled !== false, installed: !!entry,
      locked: !!locked && locked.sha256 === k.sha256 && locked.version === k.version, services: list(k.manifest?.services), requires: list(k.manifest?.requires), optional: list(k.manifest?.optional) };
  });
}

// ─── the page: which logic a game with third-party kits runs ─────────────────

/**
 * Why a game cannot run on the kit modules of `manifest` (empty: it can): a manifest of another schema, no core, a
 * kit of the game without a module, or — for a third-party kit — a module whose version or fingerprint is not the
 * one the game declares and its lock froze. Each message names the kit.
 */
export function kitModulesGapsFor(manifest: KitModulesIndex | null | undefined, kits: readonly string[], game?: ThirdPartyGame | null): string[] {
  if (!manifest || typeof manifest !== 'object') return ['no manifest'];
  const gaps: string[] = [];
  if (manifest.schema !== 'gripforge.kit-modules/1') gaps.push(`manifest schema ${String(manifest.schema)}`);
  if (!manifest.core?.wasm && !manifest.merged?.wasm) gaps.push('no core module');
  const missing = kits.filter((id) => !KITS_IN_CORE.includes(id) && !manifest.kits?.[id]?.wasm);
  if (missing.length) gaps.push(`no module for ${missing.join(', ')}`);
  if (game) gaps.push(...thirdPartyIssues(game, { modules: manifest }).filter((line) => !missing.some((id) => line.startsWith(`${id}: no kit module`))));
  return gaps;
}

/**
 * Reads the error of the loader when the kit modules do not link (`kit modules not loaded: <kit>: <reason>; …`):
 * the kits refused and why, so the page can name them. Null when the message is another error.
 */
export function refusedKitModules(message: string): Array<{ kit: string; reason: string }> | null {
  const m = /kit modules not loaded: (.*)$/s.exec(message);
  if (!m) return null;
  return m[1]!.split(/; (?=[a-z][a-z0-9_]*(?:\.[a-z][a-z0-9_]*)+: )/).map((part) => { const i = part.indexOf(': '); return i < 0 ? { kit: part, reason: 'refused' } : { kit: part.slice(0, i), reason: part.slice(i + 2) }; });
}
